/* Native section surface and typography */
&.fdp-l-membership{padding:clamp(28px,5vw,76px) clamp(18px,5vw,72px);background:#291d3b;color:#fff1d7;font-family:Georgia,serif;} &.fdp-l-membership h2{color:#fff1d7;line-height:1.06;letter-spacing:-.025em;font-size:clamp(32px,4.4vw,62px);} &.fdp-l-membership h3{color:#fff1d7;font-family:Georgia,serif;font-size:clamp(21px,2.1vw,30px);line-height:1.15;margin:0 0 14px;} &.fdp-l-membership p{color:#fff1d7;line-height:1.7;} &.fdp-l-membership .fdp-content{max-width:1160px;margin:24px auto 0;} &.fdp-l-membership .fdp-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;} &.fdp-l-membership .fdp-card{padding:clamp(22px,3vw,40px);background:#352649;border:1px solid #82688f;} &.fdp-l-membership .fdp-card p{margin-bottom:0;} &.fdp-l-membership .fdp-kicker{font-family:Arial,sans-serif;font-size:12px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;margin:0 0 18px;} &.fdp-l-membership .fdp-action{display:inline-flex;align-items:center;justify-content:center;gap:12px;min-height:48px;padding:14px 24px;background:#e6c17c;color:#201725;font:700 13px/1.3 Arial,sans-serif;letter-spacing:.06em;text-decoration:none;} &.fdp-l-membership .fdp-action:focus-visible{outline:3px solid #fff1d7;outline-offset:4px;} &.fdp-l-membership .fdp-action:hover{text-decoration:underline;} &.fdp-l-membership .fdp-actions{margin:28px 0 0;} &.fdp-l-membership .fdp-number{display:block;color:#e6c17c;font:700 13px/1.2 Arial,sans-serif;letter-spacing:.15em;margin-bottom:20px;} &.fdp-l-membership .fdp-list{margin:0;padding:0;list-style:none;} &.fdp-l-membership .fdp-list li{padding:16px 0;border-bottom:1px solid #82688f;line-height:1.6;} @media(max-width:720px){&.fdp-l-membership .fdp-grid{grid-template-columns:1fr;} &.fdp-l-membership .fdp-card{padding:24px;} &.fdp-l-membership .fdp-action{width:100%;box-sizing:border-box;}} &.fdp-l-membership .fdp-lounge-pass{display:grid;grid-template-columns:1fr 1.1fr;border:1px solid #82688f;}&.fdp-l-membership .fdp-lounge-title{padding:clamp(28px,4vw,54px);background:#352649;}&.fdp-l-membership .fdp-lounge-title h3{font-size:clamp(30px,3vw,44px);}&.fdp-l-membership .fdp-lounge-details{padding:16px clamp(28px,4vw,54px);}&.fdp-l-membership .fdp-lounge-details article{padding:24px 0;border-bottom:1px solid #82688f;}&.fdp-l-membership .fdp-lounge-details article:last-child{border-bottom:0;}&.fdp-l-membership .fdp-lounge-details h3{font-size:25px;}&.fdp-l-membership .fdp-number{margin-bottom:12px;}@media(max-width:720px){&.fdp-l-membership .fdp-lounge-pass{grid-template-columns:1fr;}}
/* Keep content within the section on narrow screens */
&.fdp-l-membership,&.fdp-l-membership *{box-sizing:border-box;}&.fdp-l-membership .fdp-content,&.fdp-l-membership .fdp-content>*,&.fdp-l-membership .fdp-content article,&.fdp-l-membership .fdp-content aside{min-width:0;}&.fdp-l-membership p,&.fdp-l-membership li,&.fdp-l-membership a{overflow-wrap:break-word;}
&.fdp-l-membership{background:#291d3b!important;color:#fff1d7!important;} &.fdp-l-membership h2,&.fdp-l-membership .text-primary{color:#fff1d7!important;}
&.fdp-l-membership .text-responsive{color:#fff1d7!important;}
